responses.output:
module "redpanda_byovnet" {
  source  = "redpanda-data/redpanda-byovnet/azure"
  version = "~> 2.0"
  region  = var.region
  azure_subscription_id = var.azure_subscription_id
  tags    = local.tags
}

resource "redpanda_resource_group" "this" {
  name = "prod"
}

resource "redpanda_network" "this" {
  name              = "prod-byovnet"
  resource_group_id = redpanda_resource_group.this.id
  cloud_provider    = "azure"
  region            = var.region
  cluster_type      = "byoc"
  customer_managed_resources {
    azure {
      # ... wired from module.redpanda_byovnet outputs
    }
  }
}

resource "redpanda_cluster" "this" {
  name              = "prod-byovnet"
  resource_group_id = redpanda_resource_group.this.id
  network_id        = redpanda_network.this.id
  cloud_provider    = "azure"
  region            = var.region
  cluster_type      = "byoc"
  connection_type   = "private"
  throughput_tier   = var.throughput_tier
  zones             = var.zones
  tags              = local.tags
  customer_managed_resources {
    azure {
      # ... wired from module.redpanda_byovnet outputs
    }
  }
}

output "cluster_id" { value = redpanda_cluster.this.id }
output "network_id" { value = redpanda_network.this.id }
output "byovnet"    { value = module.redpanda_byovnet }
